local _, WFJ = ...
WFJ.Data.add("quest", {
  [79007] = { "... e quel biglietto che hai trovato", "I resti carbonizzati del biglietto sono la tua unica guida.", "<Mentre il debole bagliore delle braci si spegne, t'imbatti nei resti di un fuoco recente.\n\nTra le provviste sparse, scopri un biglietto pieno di bruciature.>\n\n«Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo.»", nil, nil, 0x5aedabd1, 0xb4126cf2, 0x9304bba3, nil, nil, "...mm" },
  [79008] = { "... e quel biglietto che hai trovato", "I resti carbonizzati del biglietto sono la tua unica guida.", "<Mentre il debole bagliore delle braci si spegne, t'imbatti nei resti di un fuoco recente.\n\nTra le provviste sparse, scopri un biglietto pieno di bruciature.>\n\n«Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo.»", nil, "Mentre t'imbatti nei resti dell'ennesimo cadavere carbonizzato, il tuo sguardo cade su un messaggio fissato a un'asse di legno.", 0x5aedabd1, 0xb4126cf2, 0x9304bba3, nil, 0xf149b5be, "...m." },
  [79090] = { "Respingere gli invasori", "Porta il Warsong Outrider Mark a Felore Moonray, sacerdotessa della Luna, alla base del Pozzo Lunare a ⟦Ashenvale=Valtetra⟧.", "Alcuni dei ⟦Warsong Outriders=Predoni Cantaguerra⟧ giacciono sconfitti, ma la battaglia infuria ancora...", nil, nil, 0xd7957bbe, 0xdef0139e, 0x793d0d29, nil, nil, "...mm" },
  [79091] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Dici che viene dalla biblioteca di ⟦Ironforge=Forgiardente⟧? ...Di certo non ne sentiranno la mancanza.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, portamele.", 0x009cff45, nil, nil, 0x1400fbf0, 0xba293cb0, "emm.." },
  [79092] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Grazie ai tuoi sforzi il nostro sapere cresce.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, portamele.", 0x276fbac6, nil, nil, 0x1400fbf0, 0xe184a784, "emm.." },
  [79093] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Grazie ai tuoi sforzi il nostro sapere cresce.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, portamele.", 0x24c45025, nil, nil, 0x1400fbf0, 0xe184a784, "emm.." },
  [79094] = { nil, nil, nil, nil, nil, 0xfaffd003, nil, nil, nil, nil, "emmmm" },
  [79095] = { nil, nil, nil, nil, nil, 0xcbb1ebc8, nil, nil, nil, nil, "emmmm" },
  [79096] = { nil, nil, nil, nil, nil, 0x673b8f25, nil, nil, nil, nil, "emmmm" },
  [79097] = { nil, nil, nil, "Hai portato qualcosa da aggiungere alla nostra collezione?", "Grazie, {name}. Grazie ai tuoi sforzi il nostro sapere cresce.\n\nSe scopri altre opere magiche che potrebbero giovare alla biblioteca, portamele.", 0x3e745b06, nil, nil, 0x1400fbf0, 0xe184a784, "emm.." },
  [79098] = { "Ripulisci la foresta!", "Porta il Silverwing Sentinel Charm a Kazragore, veggente, alla base del Falò a ⟦Ashenvale=Valtetra⟧.", "Questo è morto, ma questi esasperanti membri dell'Alleanza continuano a combattere... che cos'è questo talismano?", nil, nil, 0x47bae5fc, 0x072ac677, 0x0d462d55, nil, nil, "...mm" },
  [79192] = { "Passo dopo passo", "Stacchi il biglietto dall'asse e leggi la scrittura scarabocchiata.", "Il biglietto comincia così: «Mission ha detto che facevano entrambi consegne per la nuova piaga. A me sembrano semplici incidenti da speziali. Trova il mio angolino tranquillo sulle montagne tra le ⟦The Barrens=Savane⟧ e ⟦Desolace=Desolanda⟧, se vuoi un posto sicuro per parlare.»", nil, "Avventurieri delle terre selvagge e mercenari si accampano qui, senza dubbio. L'angolo di un biglietto che sventola nella brezza attira la tua attenzione, e allunghi la mano per prenderlo.", 0x9dd88a3c, 0x42f58b36, 0x18dc9772, nil, 0xf47f0ef5, "...m." },
  [79229] = { "Rapina sulla strada", "Trova qualcuno a ⟦Desolace=Desolanda⟧ che sappia qualcosa dell'accampamento saccheggiato.", "L'accampamento davanti a te è uno spettacolo raccapricciante. A giudicare dai resti, le vittime erano due umani e un nano. I segni sulle ossa indicano un attacco feroce, ma le provviste saccheggiate ti dicono che non è stato un animale. E le ferite non corrispondono nemmeno alle armi dei centauri.\n\nForse uno sciacallo esperto di queste terre saprebbe che cosa pensarne.", nil, nil, 0x3d1fe3af, 0xab3965fc, 0xaa70b186, nil, nil, "...mm" },
  [79235] = { "In fuga", "Trova uno dei predoni di ⟦Desolace=Desolanda⟧.", "Ho trovato un paio di scene come quella che descrivi, {name}. Sempre accampamenti di umani e nani. Tra le carovane si dice che sia stato un gruppo di predoni dell'⟦Horde=Orda⟧. Pare probabile, viste le vittime e la brutalità degli attacchi.\n\nA quanto pare i banditi sono fuggiti da ⟦Desolace=Desolanda⟧ quando un maresciallo dell'⟦Alliance=Alleanza⟧ si è messo sulle loro tracce.\n\nSe vuoi rintracciarne uno, io darei un'occhiata alla ⟦Booty Bay=Baia del Bottino⟧. Nei porti c'è sempre gente losca che va e viene. Potresti beccarne uno che cerca un passaggio in nave per qualche posto.", nil, nil, 0xf2526006, 0x70272baf, 0xd8c30f25, nil, nil, "...mm" },
  [79236] = { "Una ciliegia per i tuoi pensieri?", "Porta un ⟦Cherry Grog=Grog alla Ciliegia⟧ a Tokal, alla ⟦Booty Bay=Baia del Bottino⟧, per sentire il resto della sua storia.", "Sei con il maresciallo? No, non sembri.\n\nLe voci che hai sentito sono vere solo a metà. Sì, saccheggiavamo gli accampamenti di umani e nani, ma non lo facevamo per l'⟦Horde=Orda⟧. Lavoravamo per un privato.\n\nTi racconterò tutta la storia se mi offri un po' di grog.", nil, nil, 0xd1679730, 0xaf00f503, 0xc6745099, nil, nil, "...mm" },
  [79242] = { "Nessun onore tra i ladri", "Trova Illari Duskfeather sulla costa degli ⟦Arathi Highlands=Altopiani d'Arathi⟧ e accedi al suo nascondiglio di bottino rubato.", "Come dicevo...\n\nIl nostro capo non era dell'⟦Horde=Orda⟧. Era un'elfa della notte di nome Illari Duskfeather. Ci dava informazioni sugli accampamenti e ci lasciava persino tenere gran parte del bottino. Si teneva solo alcuni dei pezzi più rari.\n\nPerò, quando il maresciallo ci è stato alle calcagna, ci ha lasciati per morti. Non so quali fossero le sue intenzioni, ma credo che ci abbia usati come capri espiatori.\n\nNon sono il tipo che cerca vendetta, ma non fermerò chi vuole darle la caccia. Se la stai cercando, una volta ha parlato di un nascondiglio sulla costa di Arathi.", nil, nil, 0x4053d811, 0x8394b9d9, 0xbe882b9e, nil, nil, "...mm" },
  [79358] = { "Tempesta, terra e fuoco", "Raccogli $N1 Twisted Fire Totem, $N2 Twisted Earth Totem, $N3 Twisted Air Totem e $N4 Twisted Water Totem per Veyric Thunderhame, negli ⟦Arathi Highlands=Altopiani d'Arathi⟧.", "Inondare ⟦Thousand Needles=Millepicchi⟧ non è un'impresa da poco, {name}. Se non avessi sentito di persona l'ira degli elementi, non ci avrei mai creduto. Eppure eccoci qua.\n\nI verrospini non sono i primi a usare gli elementi come armi in modo sconsiderato, e non saranno gli ultimi. Se vogliamo preparare un nostro contro-rituale, dobbiamo capire meglio questi elementi distorti. Prendi questo libro. Descrive i molti abitanti di Azeroth e il modo in cui praticano lo sciamanesimo.\n\nSe riesci a imparare da loro, forse troveremo una soluzione.", nil, nil, 0x7f68981f, 0xdaa7679c, 0xac92210f, nil, nil, "...mm" },
  [79360] = { "Aiuto elementale", "Sconfiggi ⟦Charlga Razorflank=Charlga Fiancospino⟧ nelle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧ e raccogli informazioni sui piani dei verrospini.", "Ora che padroneggi gli elementi, hai un obbligo verso di loro, e quindi verso tutta Azeroth. Noi li chiamiamo in aiuto, non pretendiamo il loro potere. È tempo che tu ricambi i favori che ti sono stati concessi. E credo di sapere come.\n\nI verrospini piegano gli elementi ai loro scopi, e sembra che stiano estendendo la loro influenza entro questi confini. Entra nelle loro gallerie e metti fine a qualunque cosa stiano tramando. Queste terre vanno protette.", nil, nil, 0x3a904965, 0xd3648ee8, 0x6cf45d3c, nil, nil, "...mm" },
  [79361] = { "Tempesta, terra e fuoco", "Raccogli $N1 Twisted Fire Totem, $N2 Twisted Earth Totem, $N3 Twisted Air Totem e $N4 Twisted Water Totem per ⟦Prate Cloudseer=Prate Scruta Nubi⟧, a ⟦Thousand Needles=Millepicchi⟧.", "Dunque i verrospini intendono inondare ⟦Thousand Needles=Millepicchi⟧ con il loro sciamanesimo distorto? Sembra quasi inimmaginabile, ma hai visto con i tuoi occhi che queste creature non vanno prese alla leggera.\n\nAvrei voluto proseguire sul serio il tuo addestramento, ma ora non c'è tempo. Queste terre sono la casa di molte creature diverse, amiche e nemiche, e nessuna di loro merita una sorte simile. Dobbiamo agire.\n\nPrendi questo tomo. Era pensato per lo studio, ma ora potrebbe custodire la chiave per disperdere la tempesta in arrivo.", nil, nil, 0x7f68981f, 0xcef55429, 0x1556610d, nil, nil, "...mm" },
  [79362] = { "Lo scudo di Grant", "Trova Grant's Mace su uno degli scheletri del ⟦Raven Hill Cemetery=Cimitero di Collecorvo⟧, poi torna da Sirra Von'Indi a ⟦Darkshire=Borgoscuro⟧ per saperne di più.", "Uno scudo lasciato dallo spettro di Grant Valor, padre della famiglia Valor ed eroe di ⟦Raven Hill=Collecorvo⟧.\n\nDato che lo spirito di Grant combatte ancora i non morti, forse la sua questione in sospeso era uccidere il non morto del Flagello che lo ferì nel ⟦Raven Hill Cemetery=Cimitero di Collecorvo⟧. Probabilmente è quello in cui è ancora conficcata la sua mazza.", nil, nil, 0x55951b8a, 0xe684af82, 0x80fde678, nil, nil, "...mm" },
  [79363] = { "La spada di Silvia", "Sconfiggi $N1 Defias Night Blade e $N2 Defias Enchanter alla ⟦Addle's Stead=Cascina degli Addle⟧, poi torna da ⟦Sirra Von'Indi=Sirra Von'indi⟧ a ⟦Darkshire=Borgoscuro⟧ per saperne di più.", "Una spada lasciata dallo spirito della guardia di ⟦Raven Hill=Collecorvo⟧, Silvia Valor, che passò la vita a proteggere i civili e le loro case.\n\nDato che lo spirito di Silvia visita ancora le fattorie, forse la sua questione in sospeso era mettere in fuga i Defias che si sono stabiliti alla ⟦Addle's Stead=Cascina degli Addle⟧, a sud di ⟦Raven Hill=Collecorvo⟧.", nil, nil, 0xf920a622, 0xef4e0f85, 0x1497337f, nil, nil, "...mm" },
  [79364] = { "Occhi al cielo", "Parla con ⟦Prate Cloudseer=Prate Scruta Nubi⟧ a ⟦Thousand Needles=Millepicchi⟧.", "Il biglietto che hai trovato dice che i ⟦Razormane=Chiomaguzza⟧ si sono rintanati a ⟦Thousand Needles=Millepicchi⟧ per una sorta di rituale nascosto. Tempeste furiose e maree crescenti...\n\nI verrospini devono usare qualche crudele stregoneria appresa da Hirzek, uno sciamano che fece di tutto per distorcere gli elementi. Se intendono inondare il canyon, servirebbero poteri elementali devastanti.\n\nNon siamo attrezzati per affrontare tutto questo, ma <un/una> potente sciaman<o/a> come te avrà di certo un'idea. Torna dai tuoi alleati e vedi se riesci a trovare una risposta.", nil, nil, 0x4fb9105f, 0x3f460f76, 0xb3c28958, nil, nil, "...mm" },
  [79365] = { "Con il vento sotto le ali", "Torna da ⟦Rau Cliffrunner=Rau Scalarupi⟧ al ⟦Freewind Post=Presidio di Ventolibero⟧, a ⟦Thousand Needles=Millepicchi⟧.", "Ecco, amico, una Squall-breakers Potion è quello che ti serve. Bevila per proteggerti dagli elementi della tempesta, ma ricorda che dura solo per poco.\n\nOra va', torna dai tuoi amici in difficoltà. Non posso fare altro per te.", nil, nil, 0xeaffbe14, 0xaeb48077, 0xbd5b5b19, nil, nil, "...mm" },
  [79366] = { "Ascolta il mio richiamo", "Usa i totem distorti per porre fine al rituale dei verrospini.", "Ora che hai i totem distorti, dobbiamo usarli per evocare gli elementali corrotti che i verrospini stanno richiamando. Sconfiggili per purificare queste terre e porre fine all'abominevole rituale dei Chiomaguzza, poi riferisci il tuo successo a ⟦Rau Cliffrunner=Rau Scalarupi⟧.\n\nComincia la purificazione dalle pozze di vapore a ovest. Quella zona è ricca di ognuno degli elementi. Ma fa' attenzione, {name}. I verrospini non staranno a guardare mentre mandi all'aria i loro piani.", nil, nil, 0xb87aaede, 0x5eafbe6d, 0x6a7313ec, nil, nil, "...mm" },
  [79442] = { "Le armi della tempesta", "Consegna l'Eye of the Tempest a ⟦Bath'rah the Windwatcher=Bath'rah il Guardiavento⟧, nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Il nostro popolo non saprà mai ringraziarti abbastanza, ma io non saprei che farmene di questo occhio. Ho sentito parlare di un vecchio sciamano nelle Montagne d'Alterac che ha occhio per la magia degli elementali della tempesta. Forse potrà forgiare qualcosa per te.", nil, nil, 0x578d0b90, 0x5da19497, 0xb252f1db, nil, nil, "...mm" },
  [79483] = { "Dolci rubati del Grande Inverno", "Trova l'investigatore della Masseria Buongusto scomparso nelle regioni innevate delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Senti... non voglio rovinare la magia della stagione, ma la Masseria Buongusto avrebbe bisogno di un po' di aiuto, del tipo che voi avventurieri siete famosi per dare.\n\nCi manca un'importante spedizione di dolci che doveva rifornirci per la stagione, e ora ci manca anche l'agente della Masseria Buongusto che avevamo mandato sul campo a cercarla! Ti prego: secondo l'ultima notizia, la spedizione era nelle ⟦Alterac Mountains=Montagne d'Alterac⟧, ed è lì che il nostro uomo è andato a cercarla.\n\nVedi se sono lì, sani e salvi!", nil, nil, 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, nil, "...mm" },
  [79492] = { "⟦Metzen the Reindeer=Metzen la Renna⟧", "Trova ⟦Metzen the Reindeer=Metzen la Renna⟧. Usa le note che ti sono state date per capire dove lo tengono prigioniero.\n\nQuando trovi Metzen, tieni con te il ⟦Pouch of Reindeer Dust=Sacchetto di Polvere di Renna⟧, così potrai cospargerlo con un po' di polvere: dovrebbe liberarlo dalle catene della prigionia.\n\nUna volta liberato Metzen, riporta il ⟦Pouch of Reindeer Dust=Sacchetto di Polvere di Renna⟧ a ⟦Wulmort Jinglepocket=Wulmort Taschepiene⟧ a ⟦Ironforge=Forgiardente⟧.", "DISASTRO! Hanno rapito ⟦Metzen the Reindeer=Metzen la Renna⟧!\n\nMetzen è una delle otto renne di Babbo Inverno, ed è proprietà della Masseria Buongusto. Abbiamo ricevuto non una ma DUE lettere di riscatto da gruppi che sostengono di avere Metzen. Con le feste ormai in pieno svolgimento, qui siamo a corto di monete! Ti prego, trova Metzen e riportacelo!\n\nControlla le lettere di riscatto per trovare indizi, e cospargilo con questa polvere di renna: lo libererà da qualsiasi catena!\n\nTi prego, sbrigati!", nil, nil, 0x9cd6daf6, 0xcf081272, 0x3da2b74f, nil, nil, "...mm" },
  [79495] = { "⟦Metzen the Reindeer=Metzen la Renna⟧", "Trova ⟦Metzen the Reindeer=Metzen la Renna⟧. Usa le note che ti sono state date per trovare indizi su dove lo tengono prigioniero.\n\nQuando trovi Metzen, tieni con te il ⟦Pouch of Reindeer Dust=Sacchetto di Polvere di Renna⟧, così potrai spargergli addosso un po' di polvere: dovrebbe liberarlo dalle catene della prigionia.\n\nUna volta liberato Metzen, riporta il ⟦Pouch of Reindeer Dust=Sacchetto di Polvere di Renna⟧ a ⟦Kaymard Copperpinch=Kaymard Pinzarame⟧, a Orgrimmar.", "È successo un DISASTRO! ⟦Metzen the Reindeer=Metzen la Renna⟧ è stato rapito!\n\nMetzen è una delle otto renne di Babbo Inverno, e appartiene alla Masseria Buongusto. Abbiamo ricevuto non una ma DUE lettere di riscatto da gruppi che sostengono di avere Metzen. Con le feste in pieno svolgimento, qui siamo a corto di soldi in cassa! Ti prego, trova Metzen e riportacelo!\n\nControlla le lettere di riscatto per trovare indizi, e spargigli addosso questa polvere di renna: lo libererà da qualsiasi catena!\n\nTi prego, sbrigati!", nil, nil, 0x9cd6daf6, 0xa38abc5d, 0x80df7c2b, nil, nil, "...mm" },
  [79535] = { nil, nil, nil, nil, nil, 0xa30fcfac, nil, nil, nil, nil, "emmmm" },
  [79536] = { "Grande amico della biblioteca", nil, nil, nil, nil, 0xf10ee12c, nil, nil, nil, nil, ".mmmm" },
  [79624] = { "Chiunque può cucinare", "Trova un ogre che sappia leggere la Illegible Recipe.", "La ricetta sembra essere per una specie di piatto di carne. È scritta in una lingua che non capisci. Vista la provenienza e l'argomento, la tua ipotesi migliore è la lingua degli ogre.\n\nDi solito gli ogre non sono tipi da cucina ma, se ne conoscessi uno con questa inclinazione, potrebbe tradurti la ricetta.", nil, nil, 0x6efd80be, 0xe9aa48ab, 0xfc4de398, nil, nil, "...mm" },
  [79637] = { "Un ⟦Ticking Present=Regalo Ticchettante⟧", nil, nil, nil, nil, 0xd9f880a5, nil, nil, nil, nil, ".mmmm" },
  [79731] = { "La pergamena troll", "Risolvi l'enigma della pergamena. Fatto questo, forse Hemet Nesingwary vorrà sentire la storia.", "<Gli antichi glifi si trasformano in parole davanti ai tuoi occhi.>\n\nQuando la fontana di Zul'Kunda scorrerà con le acque della sorgente sacra, gli dei concederanno la loro benedizione.", nil, nil, 0xfd4a85b9, 0x4e2761f1, 0x1382b37e, nil, nil, "...mm" },
  [79947] = { nil, nil, nil, nil, nil, 0x19d978d8, nil, nil, nil, nil, "emmmm" },
  [79948] = { nil, nil, nil, nil, nil, 0x5bc13f46, nil, nil, nil, nil, "emmmm" },
  [79949] = { "Una rete di menzogne: sfatare miti e leggende", nil, nil, nil, nil, 0xefc18e04, nil, nil, nil, nil, ".mmmm" },
  [79950] = { "I demoni e te", nil, nil, nil, nil, 0x6fe9a1ef, nil, nil, nil, nil, ".mmmm" },
  [79951] = { "Mummie: guida ai Non Morti più sgradevoli", nil, nil, nil, nil, 0x99295356, nil, nil, nil, nil, ".mmmm" },
  [79952] = { nil, nil, nil, nil, nil, 0x6bc7959f, nil, nil, nil, nil, "emmmm" },
  [79974] = { "Un lavoro bagnato", "Spolverando una borsa da messaggero che spunta dal terreno, trovi una pergamena infilata tra le provviste.", "\"Mi piace sempre tenere una scorta di riserva qui vicino, nel caso mi tocchi scappare in fretta.\n\nLa parete di questa montagna è così bella che si direbbe scolpita dalle cascate del tempo.\nQuello è il nido delle aquile: è quello che stai cercando.\"", nil, "Ingegneria nanica: sempre una meraviglia.", 0x9c808653, 0x9e139b4e, 0x631c42d4, nil, 0xb4a31145, "...m." },
  [79975] = { "Il pugno dell'aquila", "Gli spruzzi d'acqua inumidiscono l'aria: la vista è incredibile.", "<Dentro la cassetta degli attrezzi trovi una lettera piegata con cura.>\n\n\"Da qui, con gli strumenti giusti, sei tu a dettare legge. Ottimo posto per lanciarsi con un aliante a paracadute.\n\nLa mia lealtà verso l'Eagle and Fist mi impone di stare lontano, per servirli al meglio. Questa barricata ha visto giorni migliori, come gli antichi regni che un tempo difendeva, ma non l'abbandonerò mai.\"", nil, "Il fuoco del bivacco è stato appena alimentato con della legna, ma i segni di una partenza frettolosa sono evidenti.", 0xa1fb6a7a, 0xb9a33603, 0x322bb447, nil, 0x98322f53, "...m." },
  [79976] = { "Dev'essere questo il posto", "Chiunque fosse qui, l'hai mancato per un soffio.", "\"Così ho deciso di riportare il mio lavoro sottoterra. Perché non finisca nelle mani sbagliate.\"\n\n<Il foglio è strappato quanto basta per contenere il messaggio. Non sai se siano le ultime parole che leggerai dell'autore o un indizio per il prossimo nascondiglio. Un sacco a pelo legato male ti si sta srotolando sui piedi...>", nil, "Un pesante telo copre un'attrezzatura assortita. Ti prendi lo zaino.", 0x3d8d005f, 0x5d8a5aef, 0xb96b3437, nil, 0x72a36d26, "...m." },
  [79980] = { "Arrampicata", "Scopri cosa ti attende.", "\"Non male, eh? Se stai leggendo, vuol dire che la mia scorta è ancora lì. Fai cento passi dritto verso nord e non romperti le caviglie scendendo per la ripida parete della scogliera. Dovrebbe essercene abbastanza per tirare avanti.\"", nil, "Estrai dal terreno una borsa da messaggero. Infilata tra le provviste c'è una pergamena sporca.", 0x51393b00, 0xecbb9528, 0x76de52ab, nil, 0x85208ab7, "...m." },
})
